/* Original appendix laboratories. Explicit ideal logic, no device timing simulation. */
(()=>{
 'use strict';
 const M={
  pla(d){const a=(d>>2)&1,b=(d>>1)&1,c=d&1,p=[a&(1-b),b&c,(1-a)&c];return{p,f:p[0]|p[1],g:p[1]|p[2]};},
  polarity:(d,p)=>1^(((d===0)?1:0)^p),
  drive(f,en,type,pull){const drive=type==='tri'&&!en?'Z':type==='oc'&&f?'Z':f;return{drive,pin:drive==='Z'?(pull==='up'?1:pull==='down'?0:'?'):drive};},
  palNext:(q,mode,d)=>mode===0?15:mode===1?q:mode===2?d:(q+15)%16,
  lut:(mask,address)=>(mask>>address)&1,
  gate(d,kind){const bits=[(d>>2)&1,(d>>1)&1,d&1],n=bits.reduce((a,b)=>a+b,0);return kind==='and'?+(n===3):kind==='or'?+(n>0):kind==='one'?+(n===1):kind==='odd'?n%2:kind==='even'?1-n%2:kind==='equal'?+(n===0||n===3):kind==='majority'?+(n>=2):+(n!==3);},
  timing(cq,comb,su,skew,min,hold){return{period:cq+comb+su-skew,holdMargin:min-hold-skew};},
  final(q,en,reset=1){return !reset?0:!en?q:q===0?1:q===1?2:0;},
  chip(type,addr,a,b,data,en){if(type==='138')return{y:en?255^(1<<addr):255};if(type==='151')return{y:en?((data>>addr)&1):0};if(type==='85')return{gt:+(a>b),eq:+(a===b),lt:+(a<b)};let i=-1;if(en)for(let k=0;k<8;k++)if((data>>k)&1)i=k;return{y:i<0?7:7-i,valid:+(i>=0),i};}
 };
 if(typeof window!=='undefined')window.AppendixModels=M;
 if(typeof module!=='undefined')module.exports=M;
 if(typeof document==='undefined')return;
 const root=document.querySelector('[data-lab]');if(!root)return;
 const kind=root.dataset.lab,C={ink:'var(--foreground)',green:'var(--primary)',blue:'var(--blue)',orange:'var(--orange)',muted:'var(--muted-foreground)',red:'var(--red)',line:'var(--border)'};
 const E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const B=(n,w=4)=>n.toString(2).padStart(w,'0'),F=n=>String(+n.toFixed(3));
 const T=(x,y,t,anchor='start',color='ink',size=12)=>`<text x="${x}" y="${y}" text-anchor="${anchor}" style="font-size:${size}px;fill:${C[color]}">${E(t)}</text>`;
 const W=(d,color='ink',dash=false)=>`<path d="${d}" fill="none" stroke="${C[color]}" stroke-width="${color==='green'?2.5:1.5}" stroke-linejoin="round"${dash?' stroke-dasharray="4 3"':''}/>`;
 const box=(x,y,w,h,t,color='ink')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="var(--card)" stroke="${C[color]}"/>`+T(x+w/2,y+h/2+4,t,'middle',color);
 const circle=(x,y,r=4,color='ink',fill=false)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill?C[color]:'var(--card)'}" stroke="${C[color]}"/>`;
 const arrow=(x,y,u,v,color='green')=>{const a=Math.atan2(v-y,u-x);return W(`M${x} ${y} L${u} ${v} M${u-6*Math.cos(a-.5)} ${v-6*Math.sin(a-.5)} L${u} ${v} L${u-6*Math.cos(a+.5)} ${v-6*Math.sin(a+.5)}`,color);};
 const ground=(x,y)=>W(`M${x} ${y} v6 m-9 0 h18 m-14 5 h10 m-7 5 h4`);
 const ninput=(k,l,v,min,max,step=1)=>`<label>${l}<input data-key="${k}" type="number" value="${v}" min="${min}" max="${max}" step="${step}"></label>`;
 const select=(k,l,options)=>`<label>${l}<select data-key="${k}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
 const bool=(k,l)=>select(k,l,[['1','1'],['0','0']]);
 const button=(k,l)=>`<button type="button" data-action="${k}">${l}</button>`;
 const bits=(n=3)=>Array.from({length:n},(_,i)=>button('bit'+(n-i-1),'')).join('');
 let s,svg,status,render;
 function init(defaults,controls='',buttons=''){
  s={...defaults};const saved=window.openai?.widgetState?.privateContent;
  if(saved&&typeof saved==='object')for(const k in defaults)if(typeof saved[k]===typeof defaults[k]&&(typeof saved[k]!=='number'||Number.isFinite(saved[k])))s[k]=saved[k];
  root.classList.add('appendix-lab');root.innerHTML=`<div class="lab-controls">${controls}</div><div class="lab-buttons">${buttons}</div><svg role="img"></svg><div class="lab-status" role="status" aria-live="polite"></div>`;svg=root.querySelector('svg');status=root.querySelector('.lab-status');
  root.querySelectorAll('[data-key]').forEach(el=>{const k=el.dataset.key;if(el.type==='number'){s[k]=Math.max(+el.min,Math.min(+el.max,s[k]));if(+el.step===1)s[k]=Math.round(s[k]);}else if(![...el.options].some(o=>o.value===s[k]))s[k]=defaults[k];el.value=s[k];el.onchange=()=>{s[k]=el.type==='number'?Math.max(+el.min,Math.min(+el.max,+el.value)):el.value;if(el.type==='number'&&+el.step===1)s[k]=Math.round(s[k]);el.value=s[k];update();};});
  root.querySelectorAll('[data-action^="bit"]').forEach(el=>el.onclick=()=>{s.d^=1<<(+el.dataset.action.slice(3));update();});
 }
 function bind(k,f){root.querySelector(`[data-action="${k}"]`).onclick=()=>{f();update();};}
 function update(){render();root.querySelectorAll('[data-action^="bit"]').forEach(el=>{const b=+el.dataset.action.slice(3),v=(s.d>>b)&1;el.textContent=['C','B','A'][b]+' = '+v;el.setAttribute('aria-pressed',String(!!v));});window.openai?.setWidgetState({modelContent:{topic:kind,...s},privateContent:s})?.catch(()=>{});}
 function show(title,h,drawing,desc,data={}){svg.setAttribute('viewBox',`0 0 360 ${h}`);svg.setAttribute('aria-label',title);svg.innerHTML='<title>'+E(title)+'</title>'+drawing;status.textContent=desc;for(const[k,v]of Object.entries(data))svg.dataset[k]=typeof v==='object'?JSON.stringify(v):v;}
 function dff(x,y,w=70,h=90,fall=false){return box(x,y,w,h,'')+T(x+9,y+24,'1D')+T(x+9,y+65,'C1')+T(x+w-9,y+24,'Q','end')+W(`M${x} ${y+51} l9 8 -9 8`)+(fall?circle(x-4,y+59):'');}
 function tri(x,y,invert=false){return W(`M${x} ${y-24} v48 l40 -24 Z`)+(invert?circle(x+44,y):'');}
 function load(pull,x=290,y=150){if(pull==='none')return T(x,y+57,'无外部偏置','middle','muted');const up=pull==='up';return W(`M${x} ${y} v${up?-18:18}`)+`<rect x="${x-5}" y="${up?y-48:y+18}" width="10" height="30" fill="var(--card)" stroke="${C.ink}"/>`+W(`M${x} ${up?y-48:y+48} v${up?-18:15}`)+(up?T(x,y-76,'VDD','middle'):ground(x,y+63))+T(x+13,up?y-29:y+39,'R');}
 const pullControl=()=>select('pull','外接偏置',[['none','无偏置'],['up','上拉'],['down','下拉']]);
 if(kind==='x-config'){
  init({tech:'fuse',stage:'before'},select('tech','连接技术',[['fuse','熔丝'],['anti','反熔丝'],['float','浮栅MOS（课本模型）'],['sram','SRAM控制开关']])+select('stage','配置状态',[['before','原状态 / 控制0'],['after','编程后 / 控制1']]));
  render=()=>{const after=s.stage==='after',closed=s.tech==='fuse'||s.tech==='float'?!after:after;let o=T(180,27,'配置只决定连接，运行数据另行变化','middle')+W('M35 125 H120 M235 125 H325')+circle(120,125,3)+circle(235,125,3)+W(closed?'M120 125 H235':'M120 125 L220 85',closed?'green':'orange')+T(35,110,'输入端')+T(325,110,'连接目的端','end')+box(95,190,170,42,closed?'连接接通':'连接断开',closed?'green':'orange');show('可编程连接元件的两种状态',270,o,s.tech==='float'?'图示抽象“连接可用/禁用”；实际MOS还受信号及其阈值条件影响。':s.tech==='sram'?'此教学开关由SRAM位控制：0断开，1接通；掉电后配置需要恢复。':'图中从原状态到编程后状态是一次性改变；改变普通输入不能撤销。',{closed:+closed});};
 }else if(kind==='x-pla'){
  init({d:5},'',bits());render=()=>{const r=M.pla(s.d),terms=[[0,3],[2,4],[1,4]],literal=['A','A′','B','B′','C','C′'];let o='';literal.forEach((v,j)=>o+=T(47+34*j,24,v,'middle')+W(`M${47+34*j} 34 V185`,'line'));terms.forEach((row,i)=>{let y=64+53*i;o+=W(`M28 ${y} H248`,r.p[i]?'green':'ink')+box(248,y-16,38,32,'&')+W(`M286 ${y} H335`)+T(337,y-12,'P'+(i+1)+'='+r.p[i],'end');row.forEach(j=>o+=circle(47+34*j,y,3,r.p[i]?'green':'ink',true));});o+=T(18,214,'P₁=AB′；P₂=BC；P₃=A′C')+box(18,236,152,44,'F₁=P₁+P₂ = '+r.f,'green')+box(190,236,152,44,'F₂=P₂+P₃ = '+r.g,'blue')+T(18,309,'实心点＝连接；P₂可同时送往两个输出。');show('PLA的与阵列和输出组合',335,o,`ABC=${B(s.d,3)}。先求三个乘积项，再求两个输出。`,r);};
 }else if(kind==='x-pal'){
  init({type:'pla'},select('type','输出连接结构',[['pla','PLA：项可共享'],['pal','本例PAL：固定分组']]));render=()=>{const pal=s.type==='pal';let o=T(180,25,pal?'两个输出组各自生成所需项':'公共项池只生成一次BC','middle');if(!pal){['AB′','BC','A′C'].forEach((t,i)=>o+=box(20,55+i*65,70,36,t));o+=box(225,74,110,42,'F₁ = P₁+P₂')+box(225,174,110,42,'F₂ = P₂+P₃')+W('M90 73 H130 V85 H225 M90 138 H170 V105 H225 M170 138 V185 H225 M90 203 H130 V205 H225')+circle(170,138,3,'green',true);}else{[['AB′','BC'],['BC','A′C']].forEach((ts,i)=>{const y=65+115*i;o+=box(20,y,70,30,ts[0])+box(20,y+43,70,30,ts[1])+box(225,y+20,110,45,'固定或门 F'+(i+1))+W(`M90 ${y+15} H145 V${y+33} H225 M90 ${y+58} H175 V${y+52} H225`);});}show('共享项与固定分组的资源比较',315,o,pal?'同一个BC需要占用两个物理项，合计4项；不能任意借另一组的空项。':'AB′、BC、A′C共3项；BC共享给两个输出。',{terms:pal?4:3});};
 }else if(kind==='x-polarity'){
  init({d:0,p:'0'},bool('p','异或配置位p'),bits());render=()=>{const S=+(s.d===0),middle=S^(+s.p),y=M.polarity(s.d,+s.p);let o=T(180,25,'内部S=A′B′C′；最终Y=(S⊕p)′','middle')+box(15,90,75,50,'S = '+S)+W('M90 115 H125')+box(125,90,60,50,'=1')+W('M185 115 H235 M155 185 V140')+T(155,204,'p = '+s.p,'middle')+tri(235,115,true)+W('M283 115 H337')+T(210,87,'值='+middle,'middle')+T(335,148,'Y='+y,'end','green')+T(180,250,'p=0：取反；p=1：同相','middle');show('输出通路包含两次可能的反相',280,o,'先算异或，再算输出缓冲反相。不能只按配置位名字猜引脚极性。',{internal:S,middle,y});};
 }else if(kind==='x-io'||kind==='x-outputs'){
  const io=kind==='x-io';init({f:'1',en:io?'0':'1',type:'tri',pull:'up'},bool('f','内部逻辑F')+bool('en',io?'OE_n（0允许）':'EN（1允许）')+(io?'':select('type','输出结构',[['push','推挽'],['oc','L型开路'],['tri','三态']]))+pullControl());
  render=()=>{const en=io?1-(+s.en):+s.en,r=M.drive(+s.f,en,s.type,s.pull);let o=T(180,25,'驱动状态与引脚电压分别判断','middle')+box(18,125,72,50,'F = '+s.f)+W('M90 150 H125')+box(125,118,95,65,'1')+W('M220 150 H337')+circle(290,150,3,'ink',true)+load(s.pull)+T(337,175,'引脚 '+r.pin,'end','green');if(s.type==='tri')o+=W('M171 72 V118 M205 140 l-6 -10 h12 Z')+T(171,55,io?'OE_n='+s.en:'EN='+s.en,'middle')+(io?circle(171,114):'');if(s.type==='oc')o+=W('M205 134 l-6 8 6 8 6 -8 Z M198 153 H212');o+=box(35,274,290,40,'本器件驱动：'+r.drive, r.drive==='Z'?'orange':'green')+T(180,342,'Z不是逻辑0，也不是主动输出1。','middle');show(io?'输出使能与外部偏置':'不同输出级的驱动模型',370,o,'理想稳态模型。?表示没有足够条件确定电平；外部偏置电阻不是另一只强驱动输出。',{...r,en,type:s.type});};
 }else if(kind==='x-register'){
  init({x:'1',q:0},bool('x','输入X'),button('edge','送入一次上升沿')+button('reset','初态Q=0'));
  bind('edge',()=>s.q^=+s.x);bind('reset',()=>s.q=0);render=()=>{const d=(+s.x)^s.q;let o=T(180,25,'D=X⊕Q；Q仅在上升沿更新','middle')+T(15,85,'X='+s.x)+W('M15 98 H105')+box(105,78,62,60,'=1')+W('M167 98 H215')+T(190,80,'D='+d,'middle')+dff(215,74)+W('M285 98 H335 M310 98 V222 H70 V121 H105 M185 133 H215')+circle(310,98,3,'ink',true)+T(335,84,'Q='+s.q,'end','green')+T(182,151,'CLK','end')+T(180,245,'反馈使用当前Q；不在同一拍反复迭代。','middle');show('寄存器状态与组合次态',275,o,`当前Q=${s.q}，D=${d}。改变X只改变D；按时钟按钮才采样。`,{q:s.q,d});};
 }else if(kind==='x-palcount'){
  init({q:15,mode:'11',d:10},select('mode','M₁M₀',[['00','00 同步复位'],['01','01 保持'],['10','10 装入内部Q'],['11','11 计数']])+ninput('d','并行输入d / 0…15',10,0,15),button('edge','一次上升沿')+button('reset','回到初态Q=1111'));
  bind('edge',()=>s.q=M.palNext(s.q,parseInt(s.mode,2),s.d));bind('reset',()=>s.q=15);render=()=>{const y=15-s.q;let o=T(180,24,'教材PAL16R4：内部Q与外部Y互补','middle')+box(65,55,230,48,'内部 Q = '+B(s.q))+arrow(180,103,180,131)+box(85,131,190,40,'逐位反相')+arrow(180,171,180,200)+box(65,200,230,48,'外部 Y = '+B(y),'green')+T(180,280,'C₀ = '+(+(y===15))+'；当前外部十进制数 '+y,'middle');show('内部递减与外部加计数',310,o,'模式00等待有效时钟沿；输入d装入的是内部Q，外部读数是15−d。',{q:s.q,y,carry:+(y===15)});};
 }else if(kind==='x-gal'){
  init({mode:'registered'},select('mode','OLMC工作模式',[['input','专用输入'],['comb','专用组合输出'],['feedback','反馈组合输出'],['registered','寄存器输出']]));render=()=>{const reg=s.mode==='registered',inp=s.mode==='input',fb=s.mode==='feedback'||reg;let o=T(180,24,'功能通路示意：配置后只用选中的通路','middle');if(inp)o+=box(225,85,95,45,'外部引脚')+arrow(225,107,135,107)+box(35,85,100,45,'输入缓冲')+arrow(85,130,85,205)+T(85,228,'送内部阵列','middle');else{o+=box(20,75,85,46,'与或 / 极性')+arrow(105,98,155,98)+(reg?dff(155,74):box(155,75,70,46,'旁路'))+arrow(225,98,267,98)+box(267,76,74,44,'输出级');if(reg)o+=W('M126 133 H155')+T(125,153,'CLK','end');if(fb)o+=W(reg?'M245 98 V219 H62 V121':'M341 98 H350 V219 H62 V121','green')+T(180,245,reg?'存储状态反馈；按时钟更新':'组合反馈；不可自动当成有时钟的状态机','middle');}show('GAL输出宏单元模式',280,o,reg?'跟踪D输入、Q状态、时钟、输出极性和OE。':inp?'本器件输出驱动关闭，使用输入通路。':'输出是否有记忆，要看是否经过存储单元。',{mode:s.mode});};
 }else if(kind==='x-cpld'){
  init({focus:'logic'},select('focus','观察任务',[['logic','求次态的组合逻辑'],['state','保存状态的寄存器'],['route','可编程互连与反馈']]));render=()=>{const hi=s.focus;let o=T(180,25,'CPLD模块分工示意','middle')+box(20,65,120,58,'LAB：组合逻辑',hi==='logic'?'green':'ink')+box(220,65,120,58,'LAB：寄存器',hi==='state'?'green':'ink')+box(80,190,200,48,'PIA：可编程互连',hi==='route'?'green':'ink')+arrow(140,94,220,94)+T(180,81,'D','middle')+arrow(280,123,280,190)+T(304,164,'Q')+arrow(80,190,80,123)+T(56,165,'反馈','end')+box(97,283,166,40,'I/O 与外部端口')+arrow(180,238,180,283);show('CPLD中的组合、存储与互连',345,o,'宏单元数只给资源线索；还要检查每个函数的乘积项、连接能力和时间条件。');};
 }else if(kind==='x-lut'){
  init({d:5,mask:232},'',bits()+button('write','翻转当前地址表项')+button('majority','恢复多数表决表'));
  bind('write',()=>s.mask^=1<<s.d);bind('majority',()=>s.mask=232);render=()=>{let o=T(90,25,'地址ABC','middle')+T(190,25,'配置T[i]','middle');for(let i=0;i<8;i++){const y=42+i*32;if(i===s.d)o+=`<rect x="35" y="${y}" width="200" height="30" fill="var(--accent)"/>`;o+=T(90,y+21,B(i,3),'middle')+T(190,y+21,M.lut(s.mask,i),'middle',i===s.d?'green':'ink');}o+=arrow(235,58+s.d*32,288,58+s.d*32)+T(320,62+s.d*32,'F='+M.lut(s.mask,s.d),'middle','green')+T(180,334,'T[7:0] = '+B(s.mask,8)+' = '+s.mask.toString(16).toUpperCase().padStart(2,'0')+'₁₆','middle');show('三输入单输出LUT查表',365,o,'切换ABC只改变地址；“翻转表项”会改写函数配置。表按地址0到7向下排列。',{mask:s.mask,address:s.d,y:M.lut(s.mask,s.d)});};
 }else if(kind==='x-timing'){
  init({cq:2,comb:6,su:1,skew:0,min:1.4,hold:.5},ninput('cq','tCQ,max / ns',2,.2,5,.1)+ninput('comb','tcomb,max / ns',6,1,20,.1)+ninput('su','tSU / ns',1,.1,3,.1)+ninput('skew','捕获−发射偏移s / ns',0,-2,2,.1)+ninput('min','最短数据路径总延迟 / ns',1.4,.1,6,.1)+ninput('hold','tH / ns',.5,.1,3,.1));render=()=>{const r=M.timing(s.cq,s.comb,s.su,s.skew,s.min,s.hold);let o=T(180,24,'建立看最长路径；保持看最短路径','middle')+box(15,65,82,48,'发射FF')+arrow(97,89,138,89)+box(138,65,84,48,'组合+连线')+arrow(222,89,263,89)+box(263,65,82,48,'捕获FF')+T(180,154,'T ≥ '+F(r.period)+' ns','middle','green')+T(180,186,r.period>0?'理想f上限 '+F(1000/r.period)+' MHz':'该模型未给出正的周期下限','middle')+T(180,232,'保持裕量 '+F(r.holdMargin)+' ns','middle',r.holdMargin<0?'red':'green')+T(180,264,r.holdMargin<0?'保持不满足；降低频率不修复此条件':'保持条件满足（本题参数）','middle');show('寄存器路径的建立与保持检查',300,o,'不含抖动和额外裕量；输入参数由题设给定。s>0表示捕获时钟较晚到。',r);};
 }else if(kind==='x-frame'){
  init({d:5,q:0},'',bits()+button('edge','公共C1上升沿'));
  bind('edge',()=>s.q=s.d);render=()=>{let o=box(105,30,145,52,'公共控制 C1')+W('M55 56 H105 M105 48 l9 8 -9 8')+T(50,42,'CLK','end');for(let i=0;i<3;i++){const y=82+65*i,b=2-i;o+=box(105,y,145,65,'1D')+W(`M55 ${y+32} H105 M250 ${y+32} H315`)+T(55,y+19,'D'+b+'='+((s.d>>b)&1),'end')+T(315,y+20,'Q'+b+'='+((s.q>>b)&1),'end','green');}show('公共控制与三个并行存储位',310,o,'三个D单元共享控制条件，同一沿同时采样。上下排列不代表数据串联传递。',{q:s.q,d:s.d});};
 }else if(kind==='x-convention'){
  init({a:'1',b:'0',logic:'positive'},bool('a','物理输入A：1=H，0=L')+bool('b','物理输入B：1=H，0=L')+select('logic','逻辑约定',[['positive','正逻辑'],['negative','负逻辑']]));render=()=>{const a=+s.a,b=+s.b,y=a&b,n=+(s.logic==='negative');let o=T(180,25,'固定物理关系：两输入皆H，输出才为H','middle')+box(115,60,130,70,'物理电路')+W('M35 80 H115 M35 111 H115 M245 95 H330')+T(35,67,'A '+(a?'H':'L'))+T(35,137,'B '+(b?'H':'L'))+T(330,80,'Y '+(y?'H':'L'),'end')+box(35,176,290,48,n?'负逻辑解释：Y = A + B':'正逻辑解释：Y = A · B','green')+T(180,263,`逻辑值 A=${a^n}，B=${b^n}，Y=${y^n}`,'middle');show('同一物理电路的两种逻辑约定',295,o,'只改变H/L与0/1的对应，物理电平关系不改变。不要在一次计算中随意混用约定。',{a:a^n,b:b^n,y:y^n});};
 }else if(kind==='x-gates'){
  init({d:7,type:'one'},select('type','三输入函数',[['and','&：所有输入1'],['or','≥1：至少一个1'],['one','=1：恰有一个1'],['odd','2k+1：奇数个1'],['even','2k：偶数个1'],['equal','=：所有输入相同'],['majority','≥2：多数表决'],['nand','&加圆圈：与非']]),bits());render=()=>{const labels={and:'&',or:'≥1',one:'=1',odd:'2k+1',even:'2k',equal:'=',majority:'≥2',nand:'&'},r=M.gate(s.d,s.type);let o=box(120,55,120,140,labels[s.type]);for(let i=0;i<3;i++)o+=W(`M35 ${85+i*40} H120`)+T(34,73+i*40,['A','B','C'][i]+'='+((s.d>>(2-i))&1));o+=W('M240 125 H330')+(s.type==='nand'?circle(244,125):'')+T(330,108,'Y='+r,'end','green')+T(180,245,'输入1的个数 = '+B(s.d,3).split('').filter(x=>x==='1').length,'middle');show('按定义判断三输入逻辑',280,o,'专门用111比较“恰有一个1”与“奇数个1”；再用000比较奇数与全相等。',{y:r});};
 }else if(kind==='x-edge'){
  init({d:0,clk:0,latch:0,rise:0,fall:0,history:[[0,0,0,0,0]]},'',button('d','切换D')+button('clock','切换CLK')+button('reset','恢复初态'));
  if(!Array.isArray(s.history)||s.history.some(r=>!Array.isArray(r)||r.length!==5))s.history=[[s.d,s.clk,s.latch,s.rise,s.fall]];
  const record=()=>{s.history.push([s.d,s.clk,s.latch,s.rise,s.fall]);s.history=s.history.slice(-12);};
  bind('d',()=>{s.d^=1;if(s.clk)s.latch=s.d;record();});bind('clock',()=>{s.clk^=1;if(s.clk){s.latch=s.d;s.rise=s.d;}else s.fall=s.d;record();});bind('reset',()=>{s.d=s.clk=s.latch=s.rise=s.fall=0;s.history=[[0,0,0,0,0]];});render=()=>{let o=T(180,23,'按按钮先后顺序显示理想事件','middle');const names=['D','CLK','锁存Q','上升Q','下降Q'],data=s.history;names.forEach((name,k)=>{const y=74+k*58;let p='';data.forEach((row,i)=>{const x=75+i*24,yy=y-row[k]*24;p+=(i?'H'+x+' V'+yy:'M'+x+' '+yy);});p+='h20';o+=T(10,y-8,name)+W(`M70 ${y} H346`,'line',true)+W(p,k<2?'blue':'green')+T(346,y-32,''+data[data.length-1][k],'end');});show('透明锁存与两个边沿触发的波形',365,o,`当前D=${s.d}，CLK=${s.clk}；锁存=${s.latch}，上升沿Q=${s.rise}，下降沿Q=${s.fall}。按钮动作分开，不模拟违反建立保持后的实际状态。`,{d:s.d,clk:s.clk,latch:s.latch,rise:s.rise,fall:s.fall});};
 }else if(kind==='x-dependency'){
  init({en:'1',q:0},bool('en','a → EN1'),button('edge','b端一次上升沿')+button('reset','Q回到初态0'));
  bind('edge',()=>{if(+s.en)s.q^=1;});bind('reset',()=>s.q=0);render=()=>{let o=box(120,60,130,140,'')+T(137,99,'EN1')+T(137,155,'1T')+W('M35 94 H120 M35 150 H120 M120 142 l9 8 -9 8 M250 94 H332')+T(35,80,'a='+s.en)+T(35,174,'b：上升沿')+T(331,80,'Q='+s.q,'end','green')+T(180,248,'a=1允许翻转；a=0保持','middle');show('使能关联与受控翻转事件',280,o,'编号1把EN1和1T配对，不是芯片脚号，也不是第一拍。',{q:s.q,en:+s.en});};
 }else if(kind==='x-chips'){
  init({type:'138',addr:5,a:8,b:7,data:68,en:'1'},select('type','器件',[['138','74LS138 译码'],['148','74LS148 优先编码'],['151','74LS151 选择'],['85','74LS85 比较']])+bool('en','允许工作E（综合有效条件）')+ninput('addr','138/151 地址 / 0…7',5,0,7)+ninput('data','151数据 / 148有效请求掩码',68,0,255)+ninput('a','85操作数A',8,0,15)+ninput('b','85操作数B',7,0,15));
  render=()=>{const r=M.chip(s.type,s.addr,s.a,s.b,s.data,+s.en),label={'138':'BIN/OCT','148':'HPRI/BIN','151':'MUX','85':'COMP'}[s.type];let o=box(115,55,135,190,'')+T(182,84,label,'middle');if(s.type==='138'){o+=T(130,125,'CBA')+T(30,125,B(s.addr,3))+W('M65 120 H115');for(let i=0;i<8;i++){let y=107+i*17;o+=W(`M250 ${y} H285`)+circle(254,y,3)+T(294,y+4,'Y'+i+'='+((r.y>>i)&1));}o+=T(130,220,'EN='+s.en);}else if(s.type==='148'){o+=T(182,124,'最高有效编号 '+(r.i<0?'无':r.i),'middle')+T(182,158,'编码引脚 '+B(r.y,3),'middle')+T(182,191,'有效请求 '+r.valid,'middle');}else if(s.type==='151'){o+=T(182,125,'地址 '+B(s.addr,3),'middle')+T(182,160,'数据 '+B(s.data,8),'middle')+T(182,196,'Y='+r.y+'；Y′='+(1-r.y),'middle');}else{o+=T(182,125,'A='+s.a+'，B='+s.b,'middle')+T(182,160,'> '+r.gt+'；= '+r.eq+'；< '+r.lt,'middle')+T(182,198,'低位级联设为相等','middle');}show('组合模块按功能与极性读图',285,o,s.type==='148'?'掩码中位1表示该路请求有效，即实际低有效输入为0；显示有效标志供区别“无输入”与“0号输入”。':s.type==='85'?'单片比较，级联输入固定为等于1、大于0、小于0；E对85不使用。':s.type==='138'?'E已综合三个使能的极性；E=0时所有Y_n=1。':'E表示允许工作条件；E=0时Y=0、Y′=1。本图不是三态输出。',r);};
 }else if(kind==='x-symbols'){
  init({type:'nand'},select('type','比较符号',[['nand','两输入与非'],['xor','两输入异或'],['tri','低有效使能三态反相'],['dff','上升沿D触发器'],['tff','下降沿T触发器']]));render=()=>{let o=T(95,25,'矩形表示','middle')+T(275,25,'传统表示','middle');const t=s.type;if(t==='nand'||t==='xor'){o+=box(60,70,70,85,t==='nand'?'&':'=1')+W(`M20 92 H60 M20 132 H60 M130 112 H163 M200 92 H${t==='nand'?228:238} M200 132 H${t==='nand'?228:238}`);if(t==='nand')o+=circle(134,112)+W('M228 70 H255 A42 42 0 0 1 255 154 H228 Z')+circle(301,112)+W('M305 112 H340');else o+=W('M226 70 Q255 112 226 154 Q292 158 320 112 Q292 66 226 70 M217 70 Q247 112 217 154 M320 112 H340');}else if(t==='tri'){o+=box(65,70,75,100,'1')+W('M20 105 H65 M140 105 H171 M20 148 H65 M125 127 l-6 -10 h12 Z')+circle(61,148)+circle(144,105)+T(75,153,'EN')+tri(238,105,true)+W('M200 105 H238 M286 105 H340 M252 65 V92')+circle(252,92)+T(252,55,'EN_n','middle');}else{const fall=t==='tff';o+=dff(65,70,75,100,fall)+W(`M20 94 H65 M20 129 H${fall?57:65} M140 94 H175`)+box(235,70,75,100,'')+T(245,95,fall?'T':'D')+T(245,133,'CLK')+T(302,95,'Q','end')+W(`M195 94 H235 M195 129 H${fall?227:235} M235 121 l9 8 -9 8 M310 94 H340`)+(fall?circle(231,129):'');if(fall)o=o.replace('1D','1T');}o+=T(180,222,'输入极性、输出极性、有效时刻必须一起保留。','middle');show('同一功能的两种符号画法',255,o,t==='tri'?'使能有效时Y=A′；使能无效时驱动Z。':t==='tff'?'下降沿有效且T=1时翻转；T=0保持。':t==='dff'?'只在有效上升沿采样D；此对照省略异步端。':'只比较两输入函数，输出圆圈也属于功能的一部分。');};
 }else if(kind==='x-final'){
  init({q:0,en:'1',oe:'1',rn:'1'},bool('en','计数使能E')+bool('oe','输出使能OE')+bool('rn','异步复位R_n'),button('edge','一次上升沿')+button('invalid','试验：设内部状态11'));
  bind('edge',()=>s.q=M.final(s.q,+s.en,+s.rn));bind('invalid',()=>s.q=3);render=()=>{if(!+s.rn)s.q=0;const next=M.final(s.q,+s.en,1),pin=+s.oe?B(s.q,2):'ZZ';let o=T(180,25,'三输入LUT求D；两个D触发器保存Q','middle')+box(20,65,100,100,'LUT₁ / LUT₀')+arrow(120,108,174,108)+box(174,65,85,100,'两个D FF')+arrow(259,108,296,108)+box(296,79,48,58,'三态')+W('M216 165 V236 H70 V165','green')+T(144,91,'D='+B(next,2),'middle')+T(203,193,'Q='+B(s.q,2),'end','green')+T(180,264,'引脚Y='+pin+'；下一拍D='+B(next,2),'middle')+T(180,298,'R_n=0异步复位；OE不控制计数。','middle');show('带使能与三态输出的模3计数器',330,o,'未用态11只在允许计数的下一拍回00；E=0时保持，输出禁止时内部仍可计数。',{q:s.q,next,pin});};
 }else return;
 update();
})();
